using Microsoft.EntityFrameworkCore;
namespace Indamin.Payment.Data;
public class AppDbContext(DbContextOptions<AppDbContext> options):DbContext(options){
 public DbSet<CompanySettings> CompanySettings=>Set<CompanySettings>();public DbSet<AppUser> Users=>Set<AppUser>();public DbSet<LookupValue> LookupValues=>Set<LookupValue>();public DbSet<Part> Parts=>Set<Part>();public DbSet<Supplier> Suppliers=>Set<Supplier>();public DbSet<SupplierActivity> SupplierActivities=>Set<SupplierActivity>();public DbSet<SupplierPart> SupplierParts=>Set<SupplierPart>();public DbSet<PaymentParameter> PaymentParameters=>Set<PaymentParameter>();public DbSet<SupplierPartEvaluation> SupplierPartEvaluations=>Set<SupplierPartEvaluation>();public DbSet<PaymentRun> PaymentRuns=>Set<PaymentRun>();public DbSet<PaymentRunSupplierSummary> PaymentRunSupplierSummaries=>Set<PaymentRunSupplierSummary>();public DbSet<PaymentRunInvoice> PaymentRunInvoices=>Set<PaymentRunInvoice>();public DbSet<PaymentInvoiceScore> PaymentInvoiceScores=>Set<PaymentInvoiceScore>();public DbSet<AuditLog> AuditLogs=>Set<AuditLog>();
 protected override void OnModelCreating(ModelBuilder b){
  b.Entity<CompanySettings>().ToTable("CompanySettings");b.Entity<CompanySettings>().HasKey(x=>x.Id);b.Entity<CompanySettings>().Property(x=>x.CompanyName).HasMaxLength(300);b.Entity<CompanySettings>().Property(x=>x.ShortName).HasMaxLength(100);b.Entity<CompanySettings>().Property(x=>x.SystemName).HasMaxLength(300);b.Entity<CompanySettings>().Property(x=>x.Slogan).HasMaxLength(500);b.Entity<CompanySettings>().Property(x=>x.Website).HasMaxLength(500);b.Entity<CompanySettings>().Property(x=>x.Phone).HasMaxLength(100);b.Entity<CompanySettings>().Property(x=>x.Email).HasMaxLength(200);b.Entity<CompanySettings>().Property(x=>x.EconomicCode).HasMaxLength(100);b.Entity<CompanySettings>().Property(x=>x.NationalId).HasMaxLength(100);b.Entity<CompanySettings>().Property(x=>x.PrimaryColor).HasMaxLength(20);b.Entity<CompanySettings>().Property(x=>x.SecondaryColor).HasMaxLength(20);b.Entity<CompanySettings>().Property(x=>x.LogoContentType).HasMaxLength(100);b.Entity<CompanySettings>().Property(x=>x.FaviconContentType).HasMaxLength(100);b.Entity<AppUser>().ToTable("AppUsers");b.Entity<LookupValue>().ToTable("LookupValues");b.Entity<Part>().ToTable("Parts");b.Entity<Supplier>().ToTable("Suppliers");b.Entity<SupplierActivity>().ToTable("SupplierActivities");b.Entity<SupplierPart>().ToTable("SupplierParts");b.Entity<PaymentParameter>().ToTable("PaymentParameters");b.Entity<SupplierPartEvaluation>().ToTable("SupplierPartEvaluations");b.Entity<PaymentRun>().ToTable("PaymentRuns");b.Entity<PaymentRunSupplierSummary>().ToTable("PaymentRunSupplierSummaries");b.Entity<PaymentRunInvoice>().ToTable("PaymentRunInvoices");b.Entity<PaymentInvoiceScore>().ToTable("PaymentInvoiceScores");b.Entity<AuditLog>().ToTable("AuditLogs");
  b.Entity<AppUser>().HasIndex(x=>x.UserName).IsUnique();b.Entity<LookupValue>().HasIndex(x=>new{x.GroupCode,x.Code}).IsUnique();b.Entity<Part>().HasIndex(x=>x.Code).IsUnique();b.Entity<Supplier>().HasIndex(x=>x.Code).IsUnique();b.Entity<SupplierActivity>().HasKey(x=>new{x.SupplierId,x.ActivityId});b.Entity<SupplierPart>().HasIndex(x=>new{x.SupplierId,x.PartId}).IsUnique();b.Entity<PaymentParameter>().HasIndex(x=>x.Code).IsUnique();b.Entity<SupplierPartEvaluation>().HasIndex(x=>new{x.SupplierPartId,x.PaymentParameterId}).IsUnique();b.Entity<PaymentRunSupplierSummary>().HasIndex(x=>new{x.PaymentRunId,x.SupplierId}).IsUnique();b.Entity<PaymentRunSupplierSummary>().Property(x=>x.RemainingDebt).HasPrecision(20,2);b.Entity<PaymentRunSupplierSummary>().Property(x=>x.AllocatedAmount).HasPrecision(20,2);b.Entity<PaymentRunSupplierSummary>().Property(x=>x.AllocationPercent).HasPrecision(12,8);b.Entity<PaymentRunSupplierSummary>().HasOne(x=>x.PaymentRun).WithMany(x=>x.SupplierSummaries).HasForeignKey(x=>x.PaymentRunId).OnDelete(DeleteBehavior.Cascade);b.Entity<PaymentRunInvoice>().HasIndex(x=>new{x.PaymentRunId,x.PaymentKeyHash}).IsUnique();b.Entity<PaymentInvoiceScore>().HasIndex(x=>new{x.PaymentRunInvoiceId,x.PaymentParameterId}).IsUnique();
  b.Entity<Part>().HasOne(x=>x.Type).WithMany().HasForeignKey(x=>x.TypeId).OnDelete(DeleteBehavior.Restrict);b.Entity<SupplierActivity>().HasOne(x=>x.Supplier).WithMany(x=>x.Activities).HasForeignKey(x=>x.SupplierId).OnDelete(DeleteBehavior.Cascade);b.Entity<SupplierActivity>().HasOne(x=>x.Activity).WithMany().HasForeignKey(x=>x.ActivityId).OnDelete(DeleteBehavior.Restrict);b.Entity<SupplierPart>().HasOne(x=>x.Supplier).WithMany().HasForeignKey(x=>x.SupplierId).OnDelete(DeleteBehavior.Restrict);b.Entity<SupplierPart>().HasOne(x=>x.Part).WithMany().HasForeignKey(x=>x.PartId).OnDelete(DeleteBehavior.Restrict);b.Entity<SupplierPartEvaluation>().HasOne(x=>x.SupplierPart).WithMany().HasForeignKey(x=>x.SupplierPartId).OnDelete(DeleteBehavior.Cascade);b.Entity<SupplierPartEvaluation>().HasOne(x=>x.PaymentParameter).WithMany().HasForeignKey(x=>x.PaymentParameterId).OnDelete(DeleteBehavior.Restrict);
  b.Entity<PaymentRun>().HasOne<AppUser>().WithMany().HasForeignKey(x=>x.CreatedBy).OnDelete(DeleteBehavior.Restrict);b.Entity<PaymentRun>().HasOne<AppUser>().WithMany().HasForeignKey(x=>x.ApprovedBy).OnDelete(DeleteBehavior.Restrict);b.Entity<PaymentRunInvoice>().HasOne(x=>x.PaymentRun).WithMany(x=>x.Invoices).HasForeignKey(x=>x.PaymentRunId).OnDelete(DeleteBehavior.Cascade);b.Entity<PaymentRunInvoice>().HasOne<Part>().WithMany().HasForeignKey(x=>x.PartId).OnDelete(DeleteBehavior.Restrict);b.Entity<PaymentRunInvoice>().HasOne<Supplier>().WithMany().HasForeignKey(x=>x.SupplierId).OnDelete(DeleteBehavior.Restrict);b.Entity<PaymentInvoiceScore>().HasOne(x=>x.Invoice).WithMany(x=>x.Scores).HasForeignKey(x=>x.PaymentRunInvoiceId).OnDelete(DeleteBehavior.Cascade);b.Entity<PaymentInvoiceScore>().HasOne<PaymentParameter>().WithMany().HasForeignKey(x=>x.PaymentParameterId).OnDelete(DeleteBehavior.Restrict);b.Entity<AuditLog>().HasOne<AppUser>().WithMany().HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Restrict);
  b.Entity<SupplierPart>().Property(x=>x.SupplyCapacity).HasPrecision(18,2);b.Entity<PaymentParameter>().Property(x=>x.Weight).HasPrecision(8,4);b.Entity<PaymentParameter>().Property(x=>x.MaxScore).HasPrecision(8,2);b.Entity<SupplierPartEvaluation>().Property(x=>x.Score).HasPrecision(8,2);b.Entity<PaymentRun>().Property(x=>x.TotalAllocationBudget).HasPrecision(20,2);b.Entity<PaymentRun>().Property(x=>x.ImportedDebt).HasPrecision(20,2);b.Entity<PaymentRun>().Property(x=>x.RemainingDebt).HasPrecision(20,2);b.Entity<PaymentRunInvoice>().Property(x=>x.PaymentKeyHash).HasMaxLength(64).IsRequired();b.Entity<PaymentRunInvoice>().Property(x=>x.OriginalDebt).HasPrecision(20,2);b.Entity<PaymentRunInvoice>().Property(x=>x.PreviousAllocated).HasPrecision(20,2);b.Entity<PaymentRunInvoice>().Property(x=>x.RemainingDebt).HasPrecision(20,2);b.Entity<PaymentRunInvoice>().Property(x=>x.WeightedScore).HasPrecision(12,6);b.Entity<PaymentRunInvoice>().Property(x=>x.AllocationRatio).HasPrecision(12,8);b.Entity<PaymentRunInvoice>().Property(x=>x.AllocatedAmount).HasPrecision(20,2);b.Entity<PaymentInvoiceScore>().Property(x=>x.Score).HasPrecision(8,2);b.Entity<PaymentInvoiceScore>().Property(x=>x.Weight).HasPrecision(8,4);b.Entity<PaymentInvoiceScore>().Property(x=>x.WeightedContribution).HasPrecision(12,6);
 }}
